import type { MetadataRoute } from "next";
import { getPosts } from "@/lib/blog";
import { BASE_PATH, SITE_URL } from "@/lib/site";

/**
 * A newly published post shows up in the sitemap within five minutes, with no
 * redeploy: the route is cached and re-generated by ISR when this window
 * expires. Keep this at or below 300 seconds.
 */
export const revalidate = 300;

/** Slugs must be non-empty and URL-safe to be worth listing. */
function isValidSlug(slug: unknown): slug is string {
  return typeof slug === "string" && slug.trim().length > 0;
}

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const base = `${SITE_URL}${BASE_PATH}`;
  const posts = await getPosts();

  const published = posts.filter((post) => isValidSlug(post.slug));
  const latestPost = published[0]?.publishedAt;

  const entries: MetadataRoute.Sitemap = [
    // Publicly indexable static pages. `/` deliberately has no `lastModified`:
    // it is hand-written content, and a hard-coded or build-time date would be
    // a false freshness signal to crawlers.
    //
    // The URL has no trailing slash so it matches the canonical Next.js emits
    // for the homepage (`trailingSlash` is false, i.e. the non-slash form).
    {
      url: `${base}`,
      changeFrequency: "monthly",
      priority: 1,
    },
    {
      url: `${base}/blog`,
      ...(latestPost ? { lastModified: latestPost } : {}),
      changeFrequency: "weekly",
      priority: 0.8,
    },
    // One entry per published post, keyed by its real Sanity slug.
    ...published.map((post) => ({
      url: `${base}/blog/${post.slug}`,
      ...(post.publishedAt ? { lastModified: post.publishedAt } : {}),
      changeFrequency: "yearly" as const,
      priority: 0.6,
    })),
  ];

  // Guard against duplicate <loc> values (e.g. two posts sharing a slug).
  const seen = new Set<string>();
  return entries.filter((entry) => {
    if (seen.has(entry.url)) {
      return false;
    }
    seen.add(entry.url);
    return true;
  });
}
